def can_reconstruct_words(word_lengths):
    word_lengths.sort()
    words = []

    # Try to build words from the shortest to the longest
    for length in word_lengths:
        if length > len(words):
            return "NO"
        if length == 1:
            words.append("0")
        elif length == 2:
            words.append("10")
